              title: "Postman Collection v2.1 item generated from cURL",
              language: "JSON",
              code: "{\n  \"info\": {\n    \"name\": \"Converted cURL Collection\",\n    \"schema\": \"https://schema.getpostman.com/json/collection/v2.1.0/collection.json\"\n  },\n  \"item\": [\n    {\n      \"name\": \"POST /v1/tokens\",\n      \"request\": {\n        \"method\": \"POST\",\n        \"header\": [\n          { \"key\": \"Content-Type\", \"value\": \"application/json\" }\n        ],\n        \"body\": {\n          \"mode\": \"raw\",\n          \"raw\": \"{\"grant_type\":\"client_credentials\"}\",\n          \"options\": { \"raw\": { \"language\": \"json\" } }\n        },\n        \"url\": {\n          \"raw\": \"https://api.example.com/v1/tokens\",\n          \"protocol\": \"https\",\n          \"host\": [\"api\", \"example\", \"com\"],\n          \"path\": [\"v1\", \"tokens\"]\n        }\n      }\n    }\n  ]\n}",
