              code: "syntax = \"proto3\";\npackage api.v1;\n\nenum Role {\n  ROLE_UNSPECIFIED = 0;\n  ROLE_ADMIN = 1;\n  ROLE_MEMBER = 2;\n}\n\nmessage User {\n  string id = 1;\n  string email = 2;\n  Role role = 3;\n  repeated string scopes = 4;\n}",
