              language: "javascript",
              code: "function getJwtExpiryStatus(payload, clockSkewSec = 30) {\n  const nowSec = Math.floor(Date.now() / 1000);\n  const remainingSec = payload.exp - nowSec;\n  const isExpired = nowSec >= payload.exp + clockSkewSec;\n  const notYetValid = typeof payload.nbf === 'number' && nowSec + clockSkewSec < payload.nbf;\n  return { remainingSec, isExpired, notYetValid };\n}",
